// Artifacts generated during a call, including messages, recordings, transcript, logs, packet capture, workflow-node data, variables, performance metrics, structured outputs, scorecards, and transfers.
var (
	artifactFieldMessages                        = big.NewInt(1 << 0)
	artifactFieldMessagesOpenAiFormatted         = big.NewInt(1 << 1)
	artifactFieldRecordingUrl                    = big.NewInt(1 << 2)
	artifactFieldStereoRecordingUrl              = big.NewInt(1 << 3)
	artifactFieldVideoRecordingUrl               = big.NewInt(1 << 4)
	artifactFieldVideoRecordingStartDelaySeconds = big.NewInt(1 << 5)
	artifactFieldRecording                       = big.NewInt(1 << 6)
	artifactFieldTranscript                      = big.NewInt(1 << 7)
	artifactFieldPcapUrl                         = big.NewInt(1 << 8)
	artifactFieldLogUrl                          = big.NewInt(1 << 9)
	artifactFieldNodes                           = big.NewInt(1 << 10)
	artifactFieldAssistantActivations            = big.NewInt(1 << 11)
	artifactFieldVariableValues                  = big.NewInt(1 << 12)
	artifactFieldPerformanceMetrics              = big.NewInt(1 << 13)
	artifactFieldStructuredOutputs               = big.NewInt(1 << 14)
	artifactFieldScorecards                      = big.NewInt(1 << 15)
	artifactFieldTransfers                       = big.NewInt(1 << 16)
	artifactFieldStructuredOutputsLastUpdatedAt  = big.NewInt(1 << 17)
)

type Artifact struct {
	// These are the messages that were spoken during the call.
	Messages []*ArtifactMessagesItem `json:"messages,omitempty" url:"messages,omitempty"`
	// These are the messages that were spoken during the call, formatted for OpenAI.
	MessagesOpenAiFormatted []*OpenAiMessage `json:"messagesOpenAIFormatted,omitempty" url:"messagesOpenAIFormatted,omitempty"`
	// This is the recording url for the call. To enable, set `assistant.artifactPlan.recordingEnabled`.
	RecordingUrl *string `json:"recordingUrl,omitempty" url:"recordingUrl,omitempty"`
	// This is the stereo recording url for the call. To enable, set `assistant.artifactPlan.recordingEnabled`.
	StereoRecordingUrl *string `json:"stereoRecordingUrl,omitempty" url:"stereoRecordingUrl,omitempty"`
	// This is video recording url for the call. To enable, set `assistant.artifactPlan.videoRecordingEnabled`.
	VideoRecordingUrl *string `json:"videoRecordingUrl,omitempty" url:"videoRecordingUrl,omitempty"`
	// This is video recording start delay in ms. To enable, set `assistant.artifactPlan.videoRecordingEnabled`. This can be used to align the playback of the recording with artifact.messages timestamps.
	VideoRecordingStartDelaySeconds *float64 `json:"videoRecordingStartDelaySeconds,omitempty" url:"videoRecordingStartDelaySeconds,omitempty"`
	// This is the recording url for the call. To enable, set `assistant.artifactPlan.recordingEnabled`.
	Recording *Recording `json:"recording,omitempty" url:"recording,omitempty"`
	// This is the transcript of the call. This is derived from `artifact.messages` but provided for convenience.
	Transcript *string `json:"transcript,omitempty" url:"transcript,omitempty"`
	// This is the packet capture url for the call. This is only available for `phone` type calls where phone number's provider is `vapi` or `byo-phone-number`.
	PcapUrl *string `json:"pcapUrl,omitempty" url:"pcapUrl,omitempty"`
	// This is the url for the call logs. This includes all logging output during the call for debugging purposes.
	LogUrl *string `json:"logUrl,omitempty" url:"logUrl,omitempty"`
	// This is the history of workflow nodes that were executed during the call.
	Nodes []*NodeArtifact `json:"nodes,omitempty" url:"nodes,omitempty"`
	// Ordered list of assistants that were active during the call, including after transfers and handoffs.
	AssistantActivations []*AssistantActivation `json:"assistantActivations,omitempty" url:"assistantActivations,omitempty"`
	// These are the variable values at the end of the workflow execution.
	VariableValues map[string]any `json:"variableValues,omitempty" url:"variableValues,omitempty"`
	// This is the performance metrics for the call. It contains the turn latency, broken down by component.
	PerformanceMetrics *PerformanceMetrics `json:"performanceMetrics,omitempty" url:"performanceMetrics,omitempty"`
	// These are the structured outputs that will be extracted from the call.
	// To enable, set `assistant.artifactPlan.structuredOutputIds` with the IDs of the structured outputs you want to extract.
	StructuredOutputs map[string]any `json:"structuredOutputs,omitempty" url:"structuredOutputs,omitempty"`
	// These are the scorecards that have been evaluated based on the structured outputs extracted during the call.
	// To enable, set `assistant.artifactPlan.scorecardIds` or `assistant.artifactPlan.scorecards` with the IDs or objects of the scorecards you want to evaluate.
	Scorecards map[string]any `json:"scorecards,omitempty" url:"scorecards,omitempty"`
	// These are the transfer records from warm transfers, including destinations, transcripts, and status.
	Transfers []string `json:"transfers,omitempty" url:"transfers,omitempty"`
	// This is when the structured outputs were last updated
	StructuredOutputsLastUpdatedAt *time.Time `json:"structuredOutputsLastUpdatedAt,omitempty" url:"structuredOutputsLastUpdatedAt,omitempty"`

	// Private bitmask of fields set to an explicit value and therefore not to be omitted
	explicitFields *big.Int `json:"-" url:"-"`

	extraProperties map[string]interface{}
	rawJSON         json.RawMessage
}

