const (
	OrgChannelDaily   OrgChannel = "daily"
	OrgChannelDefault OrgChannel = "default"
	OrgChannelWeekly  OrgChannel = "weekly"
	OrgChannelIntuit  OrgChannel = "intuit"
	OrgChannelHcs     OrgChannel = "hcs"
)

func NewOrgChannelFromString(s string) (OrgChannel, error) {
	switch s {
	case "daily":
		return OrgChannelDaily, nil
	case "default":
		return OrgChannelDefault, nil
	case "weekly":
		return OrgChannelWeekly, nil
	case "intuit":
		return OrgChannelIntuit, nil
	case "hcs":
		return OrgChannelHcs, nil
	}
	var t OrgChannel
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

